urlset:
{%- for file in pages -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) %}
    {%- set m = file.page.meta or {} %}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {% if m.git_revision_date_localized_raw_iso_date %}{{ m.git_revision_date_localized_raw_iso_date }}{% elif file.page.update_date %}{{ file.page.update_date }}{% endif %}

    {%- endif -%}
{% endfor %}
